<script setup lang="ts">
import { onMounted, ref } from "vue";
import { HttpStaffApi } from "../features/staff/api";
import type { ExamRevision, ExamSummary, QuestionSummary } from "../features/staff/types";
import { messageFrom, formatDate } from "../features/staff/helpers";
import ScopeSwitcher from "../components/ScopeSwitcher.vue";

const api = new HttpStaffApi();
const exams = ref<readonly ExamSummary[]>([]);
const questions = ref<readonly QuestionSummary[]>([]);
const questionCursor = ref<string | null>(null);
const pickerSearch = ref("");
const pickerLoading = ref(false);
const selected = ref<ExamRevision | null>(null);
const search = ref("");
const loading = ref(true);
const error = ref("");
const report = ref<{ isReady: boolean; errorCount: number; warningCount: number; issues: readonly { severity: string; message: string; fieldPath: string }[] } | null>(null);
const saving = ref(false);
const form = ref({ subjectId: "", title: "", instructionsHtml: "", durationSeconds: 3600, shuffleQuestions: false, shuffleOptions: false });

async function load(): Promise<void> { loading.value = true; try { exams.value = (await api.exams(search.value)).items; await loadQuestions(true); } catch (cause) { error.value = messageFrom(cause, "Daftar ujian belum tersedia."); } finally { loading.value = false; } }
async function loadQuestions(reset = false): Promise<void> { pickerLoading.value = true; try { const page = await api.questions(pickerSearch.value, reset ? undefined : questionCursor.value ?? undefined); questions.value = reset ? page.items : [...questions.value, ...page.items]; questionCursor.value = page.nextCursor; } catch (cause) { error.value = messageFrom(cause, "Question picker belum tersedia."); } finally { pickerLoading.value = false; } }
function open(exam?: ExamSummary): void { report.value = null; if (!exam) { selected.value = { id: "new", examId: "new", title: "", instructionsHtml: "", durationSeconds: 3600, shuffleQuestions: false, shuffleOptions: false, status: "DRAFT", updatedAt: "", questions: [] }; form.value = { ...form.value, subjectId: "", title: "", instructionsHtml: "", durationSeconds: 3600, shuffleQuestions: false, shuffleOptions: false }; return; } void api.examRevision(exam.revisionId).then((value) => { selected.value = value; form.value = { subjectId: exam.subjectId, title: value.title, instructionsHtml: value.instructionsHtml, durationSeconds: value.durationSeconds, shuffleQuestions: value.shuffleQuestions, shuffleOptions: value.shuffleOptions }; }).catch((cause) => { error.value = messageFrom(cause); }); }
function close(): void { selected.value = null; report.value = null; }
async function save(): Promise<void> { if (!selected.value) return; saving.value = true; try { const payload = { ...form.value }; selected.value = selected.value.id === "new" ? await api.createExam(payload) : await api.updateExam(selected.value.id, payload, selected.value.updatedAt); await load(); } catch (cause) { error.value = messageFrom(cause); } finally { saving.value = false; } }
async function validate(): Promise<void> { if (!selected.value || selected.value.id === "new") return; try { report.value = await api.validateExam(selected.value.id); } catch (cause) { error.value = messageFrom(cause); } }
async function publish(): Promise<void> { if (!selected.value || !report.value?.isReady) return; if (!window.confirm("Publish revision ujian?")) return; try { selected.value = await api.publishExam(selected.value.id, selected.value.updatedAt); await load(); } catch (cause) { error.value = messageFrom(cause); } }
async function addQuestion(item: QuestionSummary): Promise<void> { if (!selected.value || selected.value.id === "new") return; try { selected.value = await api.addExamQuestion(selected.value.id, { questionRevisionId: item.id, points: "1.00" }, selected.value.updatedAt); } catch (cause) { error.value = messageFrom(cause); } }
async function removeQuestion(id: string): Promise<void> { if (!selected.value || selected.value.id === "new") return; try { selected.value = await api.removeExamQuestion(selected.value.id, id, selected.value.updatedAt); } catch (cause) { error.value = messageFrom(cause); } }
async function move(index: number, direction: -1 | 1): Promise<void> { if (!selected.value || selected.value.id === "new") return; const target = index + direction; if (target < 0 || target >= selected.value.questions.length) return; const ids = selected.value.questions.map((q) => q.questionRevisionId); const current = ids[index]; const next = ids[target]; if (current === undefined || next === undefined) return; ids[index] = next; ids[target] = current; try { selected.value = await api.reorderExamQuestions(selected.value.id, ids, selected.value.updatedAt); } catch (cause) { error.value = messageFrom(cause); } }
onMounted(() => { void load(); });
</script>

<template>
  <header class="page-heading between"><div><p class="eyebrow">Guru · Authoring</p><h1>Ujian</h1><p class="muted">Bangun revision immutable dengan picker soal paginated dan readiness report.</p></div><button class="btn-primary" type="button" @click="open()">Buat ujian</button></header>
  <ScopeSwitcher />
  <form class="toolbar search-form" @submit.prevent="load"><label class="sr-only" for="exam-search">Cari ujian</label><input id="exam-search" v-model="search" placeholder="Cari judul ujian" /><button class="btn-secondary" type="submit">Cari</button></form>
  <div v-if="error" class="alert alert-error" role="alert">{{ error }}</div>
  <section class="card table-card"><div v-if="loading" class="table-state">Memuat ujian…</div><div v-else-if="exams.length === 0" class="table-state"><strong>Belum ada ujian</strong><span class="muted">Buat ujian pertama untuk mengatur jadwal.</span></div><div v-else class="table-scroll"><table><caption class="sr-only">Daftar ujian</caption><thead><tr><th>Judul</th><th>Status</th><th>Soal</th><th>Diperbarui</th><th></th></tr></thead><tbody><tr v-for="exam in exams" :key="exam.id"><td><strong>{{ exam.title }}</strong><small>ID revision {{ exam.revisionId }}</small></td><td><span class="badge">{{ exam.status }}</span></td><td>{{ exam.questionCount }}</td><td>{{ formatDate(exam.updatedAt) }}</td><td><button class="btn-quiet" type="button" @click="open(exam)">Edit</button></td></tr></tbody></table></div></section>
  <div v-if="selected" class="overlay" role="dialog" aria-modal="true" aria-labelledby="exam-editor-title"><section class="drawer"><div class="between"><div><p class="eyebrow">{{ selected.status }}</p><h2 id="exam-editor-title">Editor ujian</h2></div><button class="btn-quiet" type="button" @click="close">Tutup</button></div><form @submit.prevent="save"><div v-if="selected.id === 'new'" class="form-row"><label for="exam-subject-id">ID mata pelajaran</label><input id="exam-subject-id" v-model="form.subjectId" inputmode="numeric" pattern="[0-9]+" required /><small class="muted">Gunakan subject ID dari menu Akademik.</small></div><div class="form-row"><label for="exam-title">Judul ujian</label><input id="exam-title" v-model="form.title" required maxlength="250" /></div><div class="form-row"><label for="exam-instructions">Instruksi</label><textarea id="exam-instructions" v-model="form.instructionsHtml" rows="4" /></div><div class="form-grid"><label>Durasi (detik)<input v-model.number="form.durationSeconds" type="number" min="1" max="86400" required /></label><label class="check"><input v-model="form.shuffleQuestions" type="checkbox" /> Acak urutan soal</label><label class="check"><input v-model="form.shuffleOptions" type="checkbox" /> Acak opsi</label></div><div class="picker"><div class="between"><div><h3>Soal terpilih</h3><p class="muted">Gunakan tombol naik/turun agar reorder dapat dipakai keyboard.</p></div></div><ol class="selected-list"><li v-for="(item, index) in selected.questions" :key="item.questionRevisionId"><span>{{ item.label ?? `Revision ${item.questionRevisionId}` }}</span><span class="row-actions"><button class="btn-quiet compact" type="button" :disabled="index === 0" aria-label="Pindah ke atas" @click="move(index, -1)">↑</button><button class="btn-quiet compact" type="button" :disabled="index === selected.questions.length - 1" aria-label="Pindah ke bawah" @click="move(index, 1)">↓</button><button class="btn-quiet compact danger-text" type="button" aria-label="Hapus soal" @click="removeQuestion(item.questionRevisionId)">Hapus</button></span></li></ol><details><summary>Tambah dari question picker ({{ questions.length }} ditampilkan)</summary><form class="picker-search" @submit.prevent="loadQuestions(true)"><label class="sr-only" for="picker-search">Cari soal</label><input id="picker-search" v-model="pickerSearch" placeholder="Cari bank atau stimulus" /><button class="btn-secondary" type="submit" :disabled="pickerLoading">Cari</button></form><div v-if="pickerLoading" class="muted small-copy">Memuat soal…</div><div class="picker-list"><button v-for="question in questions" :key="question.id" class="picker-item" type="button" :disabled="selected.questions.some((item) => item.questionRevisionId === question.id)" @click="addQuestion(question)"><span>{{ question.label || question.bankName }}</span><small>{{ question.type }} · {{ question.status }}{{ selected.questions.some((item) => item.questionRevisionId === question.id) ? " · Sudah dipilih" : "" }}</small></button></div><button v-if="questionCursor" class="btn-quiet" type="button" :disabled="pickerLoading" @click="loadQuestions(false)">{{ pickerLoading ? "Memuat…" : "Muat soal berikutnya" }}</button></details></div><div v-if="report" class="readiness" :class="report.isReady ? 'ready' : 'blocked'"><strong>{{ report.isReady ? 'Siap dipublish' : `${report.errorCount} error, ${report.warningCount} warning` }}</strong><ul><li v-for="issue in report.issues" :key="`${issue.fieldPath}-${issue.message}`">{{ issue.severity }} · {{ issue.message }}</li></ul></div><div class="editor-actions"><button class="btn-secondary" type="button" @click="validate">Validasi readiness</button><button class="btn-primary" type="submit" :disabled="saving">{{ saving ? 'Menyimpan…' : 'Simpan draft' }}</button><button class="btn-secondary" type="button" :disabled="!report?.isReady" @click="publish">Publish</button></div></form></section></div>
</template>

<style scoped>
.page-heading { align-items: flex-start; margin-bottom: 18px; }.page-heading h1 { margin: 0 0 6px; }.eyebrow { margin: 0 0 4px; color: var(--primary); font-weight: 700; }.toolbar { margin: 16px 0; }.search-form { display: flex; gap: 8px; }.search-form input { min-height: 40px; min-width: min(360px, 55vw); }.table-card { padding: 20px; }.table-scroll { overflow-x: auto; } table { width: 100%; border-collapse: collapse; } th, td { padding: 12px 10px; border-bottom: 1px solid var(--border); text-align: left; vertical-align: top; } th { color: var(--muted); font-size: .8rem; } td small { display: block; color: var(--subtle); margin-top: 4px; }.table-state { display: grid; gap: 6px; justify-items: center; padding: 42px 12px; }.badge { display: inline-flex; padding: 4px 8px; border-radius: 99px; color: var(--primary); background: var(--primary-soft); font-size: .78rem; font-weight: 700; }.overlay { position: fixed; inset: 0; z-index: 20; display: flex; justify-content: flex-end; background: rgb(2 6 23 / 45%); }.drawer { width: min(760px, 100%); height: 100%; overflow: auto; padding: 24px; background: var(--surface); }.form-row textarea, .form-row input, .form-grid input { width: 100%; border: 1px solid var(--border-strong); border-radius: 8px; padding: 8px; color: var(--text); background: var(--surface); }.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }.form-grid label { display: grid; gap: 6px; font-weight: 600; }.check { display: flex !important; align-items: center; gap: 8px; }.check input { width: auto; }.picker { margin: 18px 0; padding: 14px; border: 1px solid var(--border); border-radius: 10px; }.picker h3 { margin: 0; }.selected-list { display: grid; gap: 8px; padding-left: 24px; }.selected-list li { display: flex; justify-content: space-between; gap: 10px; padding: 8px; border: 1px solid var(--border); border-radius: 8px; }.row-actions { display: flex; gap: 4px; }.compact { min-height: 32px; padding: 0 6px; }.danger-text { color: var(--danger); }.picker-search { display: flex; gap: 8px; margin-top: 10px; }.picker-search input { min-height: 40px; flex: 1; border: 1px solid var(--border-strong); border-radius: 8px; padding: 8px; color: var(--text); background: var(--surface); }.picker-list { display: grid; gap: 6px; margin-top: 10px; }.picker-item { display: flex; justify-content: space-between; gap: 10px; min-height: 42px; padding: 8px 10px; border: 1px solid var(--border); background: var(--surface); color: var(--text); text-align: left; }.picker-item small { color: var(--subtle); }.readiness { margin: 16px 0; padding: 12px; border-radius: 8px; }.readiness.ready { color: var(--success); background: var(--success-soft); }.readiness.blocked { color: var(--danger); background: var(--danger-soft); }.editor-actions { display: flex; flex-wrap: wrap; gap: 8px; }.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 600px) { .page-heading { display: grid; }.search-form input { min-width: 0; flex: 1; }.drawer { padding: 18px 14px; }.form-grid { grid-template-columns: 1fr; }.selected-list li { display: grid; }.row-actions { justify-content: flex-end; } }
</style>
